using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BusShelterConsistencyFix{const string Bus="Assets/Scenes/Oasis/3D/Prefeb/Bus stop.prefab";static BusShelterConsistencyFix(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BusShelterConsistencyFix.request"))return;File.Delete("BusShelterConsistencyFix.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var mesh=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/BusShelterUpgrade/Bus Shelter Shared Near.asset");Directory.CreateDirectory("FinalEnvironmentRoadBackup/BeforeBusShelterConsistencyFix");File.Copy(Bus,"FinalEnvironmentRoadBackup/BeforeBusShelterConsistencyFix/Bus stop.prefab",true);var prefab=PrefabUtility.LoadPrefabContents(Bus);try{var renderer=prefab.GetComponent<Renderer>();var far=prefab.transform.Find("Mobile distant shelter");if(far){far.GetComponent<MeshFilter>().sharedMesh=mesh;far.gameObject.SetActive(false);}var lod=prefab.GetComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.003f,new[]{renderer})});lod.fadeMode=LODFadeMode.None;lod.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(prefab,Bus);}finally{PrefabUtility.UnloadPrefabContents(prefab);}var copies=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name.StartsWith("Bus stop")&&f.sharedMesh==mesh).ToArray();foreach(var f in copies){var lod=f.GetComponent<LODGroup>();lod.ForceLOD(-1);var lods=lod.GetLODs();if(lods.Length!=1||lods[0].renderers[0]!=f.GetComponent<Renderer>())throw new Exception("Prefab consistency failed "+f.name);f.GetComponent<Renderer>().enabled=true;}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/BusShelterConsistencyFix.txt","SUCCESS removed coarse LOD switching from shared source prefab. All "+copies.Length+" bus stops use the same complete "+mesh.triangles.Length/3+" triangle mesh, intact BUS STOP lettering and route display at every visible distance. One material, shared mesh, zero realtime lights; existing atlas unchanged. Single distance cull only. Shader error="+ShaderUtil.ShaderHasError(copies[0].GetComponent<Renderer>().sharedMaterial.shader));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BusShelterConsistencyFix.txt",e.ToString());Debug.LogException(e);}}}
